import{Bt as e,It as t,St as n,bt as r,gt as i,nt as a,xt as o,yt as s}from"./chunks/framework.D2FS3J_H.js";var c=JSON.parse(`{"title":"UML Deployment Diagram","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"docs/deployment.md","filePath":"docs/deployment.md"}`),l={name:`docs/deployment.md`};function u(a,c,l,u,d,f){let p=e(`EmbeddedHylimoEditor`),m=e(`DiagramExample`);return t(),s(`div`,null,[c[0]||=r(`<h1 id="uml-deployment-diagram" tabindex="-1">UML Deployment Diagram <a class="header-anchor" href="#uml-deployment-diagram" aria-label="Permalink to “UML Deployment Diagram”">​</a></h1><p>To create a UML deployment diagram, use the <code>deploymentDiagram</code> function:</p><div class="language-hyl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">HyLiMo</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deploymentDiagram</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    // define elements</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A deployment diagram is built from the same classifiers as a <a href="./component.html">component diagram</a> - it adds the deployment targets a system runs on, the artifacts that are deployed onto them, and the two stereotyped dependencies which connect the two. All elements described below are also available in the <a href="./uml.html">general UML diagram</a>.</p><h2 id="type-level-and-instance-level" tabindex="-1">Type level and instance level <a class="header-anchor" href="#type-level-and-instance-level" aria-label="Permalink to “Type level and instance level”">​</a></h2><p>Every deployment target and every artifact can be written either as a type or as an instance specification, which is the form most deployment diagrams are drawn in. Naming a type as the second argument is what makes the difference: the title then becomes <code>name:Type</code> and is underlined, exactly like an <a href="./class.html#instance">instance</a>.</p>`,6),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20node(%22ApplicationServer%22)%0A%0A%20%20%20%20node(%22appServer%22%2C%20%22ApplicationServer%22)%20layout%20%7B%0A%20%20%20%20%20%20%20%20pos%20%3D%20apos(0%2C%20250)%0A%20%20%20%20%7D%0A%7D%0A`}),c[1]||=r(`<p>Both forms register the element in the diagram scope under its first argument, so the examples above are reachable as <code>ApplicationServer</code> and <code>appServer</code> respectively.</p><h2 id="elements" tabindex="-1">Elements <a class="header-anchor" href="#elements" aria-label="Permalink to “Elements”">​</a></h2><h3 id="node" tabindex="-1"><code>node</code> <a class="header-anchor" href="#node" aria-label="Permalink to “node”">​</a></h3><p>Creates a node, a computational resource, rendered as a 3D box. The title, the compartments and the nesting all behave like those of a <a href="./class.html#class">class</a>:</p>`,4),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20node(%22ApplicationServer%22)%20%7B%0A%20%20%20%20%20%20%20%20public%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20cpuCount%20%3A%20int%0A%20%20%20%20%20%20%20%20%20%20%20%20memory%20%3A%20int%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D%0A%7D%0A`}),c[2]||=i(`h4`,{id:`nesting`,tabindex:`-1`},[o(`Nesting `),i(`a`,{class:`header-anchor`,href:`#nesting`,"aria-label":`Permalink to “Nesting”`},`​`)],-1),c[3]||=i(`p`,null,[o(`Nesting is not decoration but notation: an artifact nested in a node `),i(`strong`,null,`is`),o(` a deployment, and an execution environment nested in a device `),i(`strong`,null,`is`),o(` the statement that it runs on that device.`)],-1),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20node(%22appServer%22%2C%20%22ApplicationServer%22)%20%7B%0A%20%20%20%20%20%20%20%20artifact(%22shop.war%22)%0A%20%20%20%20%7D%0A%7D%0A`}),c[4]||=r(`<p>Nodes can equally contain components, classes and further nodes.</p><h4 id="ports-provided-and-required-interfaces" tabindex="-1">Ports, provided and required interfaces <a class="header-anchor" href="#ports-provided-and-required-interfaces" aria-label="Permalink to “Ports, provided and required interfaces”">​</a></h4><p>A node is a classifier like any other, so it supports <code>port</code>, <code>provides</code> and <code>requires</code>. For details, see <a href="./component.html#ports">UML Component Diagram</a>.</p>`,3),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20node(%22Server%22)%20%7B%0A%20%20%20%20%20%20%20%20provides(%22REST%22)%0A%20%20%20%20%20%20%20%20port(0.25).requires(%22SMTP%22%2C%200.25)%0A%20%20%20%20%7D%0A%7D%0A`}),c[5]||=i(`h3`,{id:`device`,tabindex:`-1`},[i(`code`,null,`device`),o(),i(`a`,{class:`header-anchor`,href:`#device`,"aria-label":`Permalink to “device”`},`​`)],-1),c[6]||=i(`p`,null,[o(`Creates a device, a node which is a physical computational resource. It is a node carrying the `),i(`code`,null,`«device»`),o(` keyword:`)],-1),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20device(%22dbHost%22%2C%20%22DatabaseHost%22)%0A%7D%0A`}),c[7]||=i(`h3`,{id:`executionenvironment`,tabindex:`-1`},[i(`code`,null,`executionEnvironment`),o(),i(`a`,{class:`header-anchor`,href:`#executionenvironment`,"aria-label":`Permalink to “executionEnvironment”`},`​`)],-1),c[8]||=i(`p`,null,[o(`Creates an execution environment, a node which is the software container artifacts are deployed in. It is a node carrying the `),i(`code`,null,`«executionEnvironment»`),o(` keyword:`)],-1),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20device(%22appHost%22%2C%20%22ApplicationHost%22)%20%7B%0A%20%20%20%20%20%20%20%20executionEnvironment(%22JVM%22)%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20artifact(%22shop.war%22)%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D%0A%7D%0A`}),c[9]||=i(`h3`,{id:`artifact`,tabindex:`-1`},[i(`code`,null,`artifact`),o(),i(`a`,{class:`header-anchor`,href:`#artifact`,"aria-label":`Permalink to “artifact”`},`​`)],-1),c[10]||=i(`p`,null,[o(`Creates an artifact, a physical piece of information such as a file. UML marks an artifact with the `),i(`code`,null,`«artifact»`),o(` keyword, with the icon in its upper right corner, or with both; each of the two can be turned off on its own, see `),i(`a`,{href:`#config-properties`},`config properties`),o(`.`)],-1),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20artifact(%22shop.war%22)%0A%0A%20%20%20%20artifact(%22config%22%2C%20%22PropertyFile%22)%20layout%20%7B%0A%20%20%20%20%20%20%20%20pos%20%3D%20apos(0%2C%20250)%0A%20%20%20%20%7D%0A%7D%0A`}),c[11]||=i(`p`,null,`Artifacts support compartments just like the other classifiers, which is how the elements they contain are listed:`,-1),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20artifact(%22shop.war%22)%20%7B%0A%20%20%20%20%20%20%20%20section(%0A%20%20%20%20%20%20%20%20%20%20%20%20%22shop.jar%22%2C%0A%20%20%20%20%20%20%20%20%20%20%20%20%22web.xml%22%0A%20%20%20%20%20%20%20%20)%0A%20%20%20%20%7D%0A%7D%0A`}),c[12]||=i(`h3`,{id:`deploymentspec`,tabindex:`-1`},[i(`code`,null,`deploymentSpec`),o(),i(`a`,{class:`header-anchor`,href:`#deploymentspec`,"aria-label":`Permalink to “deploymentSpec”`},`​`)],-1),c[13]||=i(`p`,null,[o(`Creates a deployment specification, the parameters an artifact is deployed and executed with. It carries the `),i(`code`,null,`«deployment spec»`),o(` keyword, and its parameters are the regular `),i(`a`,{href:`./class.html#instance`},`value specifications`),o(` of a classifier:`)],-1),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20deploymentSpec(%22shopDeployment%22)%20%7B%0A%20%20%20%20%20%20%20%20values%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20deploymentLocation%20%3D%20%22%2Fopt%2Fshop%22%0A%20%20%20%20%20%20%20%20%20%20%20%20executionLocation%20%3D%20%22%2Fopt%2Fshop%2Fbin%22%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D%0A%7D%0A`}),c[14]||=r(`<h3 id="further-elements" tabindex="-1">Further elements <a class="header-anchor" href="#further-elements" aria-label="Permalink to “Further elements”">​</a></h3><p><code>component</code>, <code>instance</code>, <code>package</code> and <code>comment</code> are available as well, and behave exactly as in the <a href="./component.html">component diagram</a>.</p><h2 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to “Connections”">​</a></h2><h3 id="communication-path" tabindex="-1">Communication path <a class="header-anchor" href="#communication-path" aria-label="Permalink to “Communication path”">​</a></h3><p>A communication path between two deployment targets is a plain association, so the <code>--</code> operator already is one. The protocol is written on it as an ordinary label, wrapped in guillemets by the <code>keyword</code> function:</p>`,5),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20device(%22appHost%22%2C%20%22ApplicationHost%22)%0A%0A%20%20%20%20device(%22dbHost%22%2C%20%22DatabaseHost%22)%20layout%20%7B%0A%20%20%20%20%20%20%20%20pos%20%3D%20apos(600%2C%200)%0A%20%20%20%20%7D%0A%0A%20%20%20%20appHost%20--%20dbHost%20with%20%7B%0A%20%20%20%20%20%20%20%20label(keyword(%22JDBC%22)%2C%200.5%2C%20-25)%0A%20%20%20%20%7D%0A%7D%0A`}),c[15]||=i(`h3`,{id:`deployment-and-manifestation`,tabindex:`-1`},[o(`Deployment and manifestation `),i(`a`,{class:`header-anchor`,href:`#deployment-and-manifestation`,"aria-label":`Permalink to “Deployment and manifestation”`},`​`)],-1),c[16]||=i(`p`,null,[o(`Deploying an artifact onto a target and manifesting a model element by an artifact are both plain dependencies, distinguished from any other dependency only by their keyword. They are therefore written with the dashed arrow `),i(`code`,null,`..>`),o(` and a `),i(`code`,null,`«deploy»`),o(` respectively `),i(`code`,null,`«manifest»`),o(` label:`)],-1),n(p,{code:`deploymentDiagram%20%7B%0A%20%20%20%20artifact(%22shop.war%22)%0A%0A%20%20%20%20node(%22appServer%22%2C%20%22ApplicationServer%22)%20layout%20%7B%0A%20%20%20%20%20%20%20%20pos%20%3D%20apos(0%2C%20400)%0A%20%20%20%20%7D%0A%0A%20%20%20%20component(%22Shop%22)%20layout%20%7B%0A%20%20%20%20%20%20%20%20pos%20%3D%20apos(600%2C%20400)%0A%20%20%20%20%7D%0A%0A%20%20%20%20%60shop.war%60%20..%3E%20appServer%20with%20%7B%0A%20%20%20%20%20%20%20%20over%20%3D%20start(Position.Bottom).line(end(Position.Top))%0A%20%20%20%20%20%20%20%20label(keyword(%22deploy%22)%2C%200.5%2C%20-25)%0A%20%20%20%20%7D%0A%0A%20%20%20%20%60shop.war%60%20..%3E%20Shop%20with%20%7B%0A%20%20%20%20%20%20%20%20over%20%3D%20start(Position.BottomRight).line(end(Position.TopLeft))%0A%20%20%20%20%20%20%20%20label(keyword(%22manifest%22)%2C%200.5%2C%20-25)%0A%20%20%20%20%7D%0A%7D%0A`}),c[17]||=r(`<p>Nesting the artifact inside the target is the other notation for a deployment, see <a href="#nesting">nesting</a>.</p><h3 id="further-connections" tabindex="-1">Further connections <a class="header-anchor" href="#further-connections" aria-label="Permalink to “Further connections”">​</a></h3><p><code>dependsOn</code> connects a required to a provided interface, see <a href="./component.html#dependson">UML Component Diagram</a>. For additional connection types (associations, aggregations, etc.), refer to the <a href="./class.html">class diagram documentation</a>.</p><h2 id="config-properties" tabindex="-1">Config properties <a class="header-anchor" href="#config-properties" aria-label="Permalink to “Config properties”">​</a></h2><p>The following config properties are available for deployment diagrams:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th><th>Default value (in pixels)</th><th>Comment</th></tr></thead><tbody><tr><td><code>abstractAsProperty</code></td><td>Whether to show { abstract } after the name of abstract classifiers</td><td>false</td><td>-</td></tr><tr><td><code>providesDistance</code></td><td>Default distance of provided interfaces to the classifier outline</td><td>100</td><td>-</td></tr><tr><td><code>requiresDistance</code></td><td>Default distance of required interfaces to the classifier outline</td><td>100</td><td>-</td></tr><tr><td><code>showArtifactIcon</code></td><td>Whether to show the artifact symbol</td><td>true</td><td>-</td></tr><tr><td><code>showArtifactKeyword</code></td><td>Whether to show the artifact keyword</td><td>true</td><td>-</td></tr><tr><td><code>showComponentKeyword</code></td><td>Whether to show the component keyword</td><td>true</td><td>-</td></tr><tr><td><code>showComponentSymbol</code></td><td>Whether to show the component symbol</td><td>true</td><td>-</td></tr><tr><td><code>showDeviceKeyword</code></td><td>Whether to show the device keyword</td><td>true</td><td>-</td></tr><tr><td><code>showExecutionEnvironmentKeyword</code></td><td>Whether to show the executionEnvironment keyword</td><td>true</td><td>-</td></tr></tbody></table><h2 id="styling" tabindex="-1">Styling <a class="header-anchor" href="#styling" aria-label="Permalink to “Styling”">​</a></h2><p>The following <a href="./diagram.html#style-variables">style variables</a> are used by the deployment diagram elements:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th><th>Default value (in pixels)</th></tr></thead><tbody><tr><td><code>artifactIconSize</code></td><td>Width of the artifact symbol in the title</td><td>20</td></tr><tr><td><code>componentIconSize</code></td><td>Size of the component symbol in the title</td><td>25</td></tr><tr><td><code>providedInterfaceSize</code></td><td>Diameter of the circle of a provided interface</td><td>30</td></tr><tr><td><code>requiredInterfaceSize</code></td><td>Size of the socket of a required interface</td><td>45</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><p>The following example shows the deployment of a small shop, using most of the elements described above:</p>`,11),n(m,{id:`deployment`})])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};